import java.util.*;

public class Product {
    private String sku;

    public Product(String sku) { this.sku = sku; }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Product)) return false;
        return sku.equals(((Product) o).sku);
    }

    @Override
    public int hashCode() {
        return sku.hashCode();
    }
}

Map<Product, Integer> inventory = new HashMap<>();
inventory.put(new Product("SKU-100"), 5);

System.out.println(inventory.get(new Product("SKU-100")));   // 5 -- a DIFFERENT object, same content

import java.util.*;

List<String> key = new ArrayList<>(List.of("a"));
Map<List<String>, String> data = new HashMap<>();
data.put(key, "found me");

System.out.println(data.containsKey(key));   // true -- so far so good

key.add("b");   // mutating the key AFTER insertion changes its hashCode

System.out.println(data.containsKey(key));   // often false -- key is now "lost" in the map's internals

