import java.util.*;

List<String> strings = new ArrayList<>();
List<Integer> integers = new ArrayList<>();

System.out.println(strings.getClass());              // class java.util.ArrayList
System.out.println(integers.getClass());              // class java.util.ArrayList
System.out.println(strings.getClass() == integers.getClass());   // true

import java.util.*;

public class MaxFinder {
    public static <T extends Comparable<T>> T max(List<T> items) {
        T largest = items.get(0);
        for (T item : items) {
            if (item.compareTo(largest) > 0) {
                largest = item;
            }
        }
        return largest;
    }
}

System.out.println(MaxFinder.max(List.of(3, 7, 2, 9, 4)));          // 9
System.out.println(MaxFinder.max(List.of("pear", "apple", "kiwi"))); // pear

import java.util.*;

public class Stats {
    // producer: only reads from numbers -- ? extends Number accepts List<Integer>, List<Double>, etc.
    public static double sum(List<? extends Number> numbers) {
        double total = 0;
        for (Number n : numbers) {
            total += n.doubleValue();
        }
        return total;
    }

    // consumer: only writes into destination -- ? super Integer accepts List<Number>, List<Object>, etc.
    public static void fillWithSquares(List<? super Integer> destination, int count) {
        for (int i = 1; i <= count; i++) {
            destination.add(i * i);
        }
    }
}

List<Integer> ints = List.of(1, 2, 3);
System.out.println(Stats.sum(ints));   // 6.0

List<Number> numberBucket = new ArrayList<>();
Stats.fillWithSquares(numberBucket, 4);
System.out.println(numberBucket);   // [1, 4, 9, 16]

