class Pair<T> {
    private T first;
    private T second;

    public Pair(T first, T second) {
        this.first = first;
        this.second = second;
    }

    public T getFirst() { return first; }
}

public class Main {
    public static void main(String[] args) {
        Pair<String> namesPair = new Pair<>("Amy", "Ben");
        Pair<Integer> numbersPair = new Pair<>(1, 2);

        System.out.println(namesPair.getClass() == numbersPair.getClass());
        System.out.println(namesPair.getFirst().toUpperCase());
    }
}

class Stack<T> {
    private T[] items;
    private int size;

    public Stack(int capacity) {
        items = new T[capacity];
    }

    public void push(T item) {
        items[size++] = item;
    }

    public T pop() {
        return items[--size];
    }
}

exercises.solutionCode:
class Stack<T> {
    private Object[] items;
    private int size;

    public Stack(int capacity) {
        items = new Object[capacity];
    }

    public void push(T item) {
        items[size++] = item;
    }

    @SuppressWarnings("unchecked")
    public T pop() {
        return (T) items[--size];
    }
}

