import java.util.*;

class Task implements Comparable<Task> {
    private String name;
    private int priority;

    public Task(String name, int priority) {
        this.name = name;
        this.priority = priority;
    }

    @Override
    public int compareTo(Task other) {
        return Integer.compare(this.priority, other.priority);
    }

    @Override
    public String toString() { return name + "(p" + priority + ")"; }
}

List<Task> tasks = new ArrayList<>(List.of(
    new Task("Deploy", 3), new Task("Fix bug", 1), new Task("Write docs", 2)
));
Collections.sort(tasks);
System.out.println(tasks);   // [Fix bug(p1), Write docs(p2), Deploy(p3)]

import java.util.*;

List<Task> tasks = new ArrayList<>(List.of(
    new Task("Deploy", 3), new Task("Fix bug", 1), new Task("Write docs", 2)
));

tasks.sort(Comparator.comparing(Task::getName));
System.out.println(tasks);   // [Deploy(p3), Fix bug(p1), Write docs(p2)] -- alphabetical by name

tasks.sort(Comparator.comparingInt(Task::getPriority).reversed());
System.out.println(tasks);   // [Deploy(p3), Write docs(p2), Fix bug(p1)] -- highest priority number first

import java.util.*;

class Student {
    String name;
    String grade;
    double gpa;

    Student(String name, String grade, double gpa) {
        this.name = name; this.grade = grade; this.gpa = gpa;
    }

    public String toString() { return name + "(" + grade + ", " + gpa + ")"; }
}

List<Student> students = new ArrayList<>(List.of(
    new Student("Amy", "A", 3.8), new Student("Ben", "B", 3.9), new Student("Cara", "A", 3.9)
));

students.sort(
    Comparator.comparing((Student s) -> s.grade)
              .thenComparing(s -> s.gpa, Comparator.reverseOrder())
);
System.out.println(students);   // [Cara(A, 3.9), Amy(A, 3.8), Ben(B, 3.9)]

